CloudFront security.ejemplo:
# Política de acceso en S3 para permitir solo OAC de una distribución CloudFront
"Condition": {
  "StringEquals": {
    "AWS:SourceArn": "arn:aws:cloudfront::123456789012:distribution/EDFDVBD6EXAMPLE"
  }
}

Confidential computing.ejemplo:
# Política KMS que solo permite descifrar si la imagen del Nitro Enclave coincide con el hash PCR0 esperado
"Condition": {
  "StringEqualsIgnoreCase": {
    "kms:RecipientAttestation:PCR0": "0123456789abcdef..."
  }
}

MFA (consola).ejemplo:
# Condición IAM que deniega cualquier acción excepto gestionar su propio MFA si no hay MFA activo
"Condition": {
  "BoolIfExists": {"aws:MultiFactorAuthPresent": "false"}
}
